import z3
weeks = 6
players = 36
groups_per_week = 9
group_size = 4
group = [[z3.Int(f"g_{w}_{p}") for p in range(players)] for w in range(weeks)]
s = z3.Solver()
for w in range(weeks):
    for p in range(players):
        s.add(group[w][p] >= 0, group[w][p] < groups_per_week)
for w in range(weeks):
    for g in range(groups_per_week):
        s.add(z3.Sum([z3.If(group[w][p] == g, 1, 0) for p in range(players)]) == group_size)
for p1 in range(players):
    for p2 in range(p1+1, players):
        together = z3.Sum([z3.If(group[w][p1] == group[w][p2], 1, 0) for w in range(weeks)])
        s.add(together <= 1)
s.set('timeout', 60000)  # 60 seconds in ms
print(s.check())
if s.check() == z3.sat:
    m = s.model()
    sol = [m.evaluate(group[w][p]).as_long() for w in range(weeks) for p in range(players)]
    print(sol)
